nta.declaration:
// Map constants
const int GRID_W = 18;
const int GRID_H = 13;
const int NUM_LANES = 5;
const int MAX_VEHICLES = 4;

// Typedef

typedef int[0, GRID_W-1] PosX;
typedef int[0, GRID_H-1] PosY;

// Global variables
PosX frog_x = 9;
PosY frog_y = 0;

// Channels
chan vehicle_moving;
broadcast chan frog_moving;

template.declaration:
// Template Frog
clock x;                // local clock of Frog
clock game_clock;             

Lives lives = 3;
typedef int[1, 3] Lives;

void loose_life(){
    lives--;
}

// Template Vehicle
clock x;                    // local clock of Vehicle     

//int[0, GRID_H-1] lane = init_y;           // Initialization of the variable lane based on the input
                                            // Note that this measurement is fixed during the execution of the TA
                                            // ensuring that a vehicle stays in the same row in which is initialized 
//int[-1, GRID_W] &vehicle_x = init_x;      // Initialization of the coordinate x based on the input

void move_vehicle() {
    int i;
    for (i = 0; i < n; i++) {
        if (v[i]==-1){
            v[i] = GRID_W;
        } else {
            v[i] = v[i] - 1;
        }
    }
}

void move_right(int[-1, GRID_W]& v[MAX_VEHICLES], int n) {
    int i;
    for (i = 0; i < n; i++) {
        if (v[i]==GRID_W){
            v[i] = 0;
        } else {
            v[i] = v[i] + 1;
        }
    }
}

nta.system:
// Vehicle Lane instantiations where VehicleLane( int size, int speed, int[-1, GRID_W]& init_x[MAX_VEHICLES], int n, int[0, GRID_H-1] init_y )
// Lane OC - OrangeCar
int [-1, GRID_W] oc_x[MAX_VEHICLES] = {4, 14, 0, 0};
OC = VehicleLane(1, 2, oc_x, 2, 1);

// Lane B - Bulldozer
int [-1, GRID_W] b_x[MAX_VEHICLES] = {2, 11, 0, 0};
B = VehicleLane(1, 10, b_x, 2, 2);

// Lane GC - GreenCar
int [-1, GRID_W] gc_x[MAX_VEHICLES] = {4, 8, 12, 16};
GC = VehicleLane(1, 5, gc_x, 4, 3);

// Lane PC - PurpleCar
int [-1, GRID_W] pc_x[MAX_VEHICLES] = {2, 10, 0, 0};
PC = VehicleLane(1, 4, pc_x, 2, 4);

// T - Truck
// T1 = Vehicle(2, 7, 4, 5);
// T2 = Vehicle(2, 7, 15, 5);
int [-1, GRID_W] t_x[MAX_VEHICLES] = {4, 15, 0, 0};
T = VehicleLane(2, 7, t_x, 2, 5);

// List one or more processes to be composed into a system.
system OC, B, GC, PC, T;
